import{St as e,at as t,it as n,n as r,st as i,vt as a}from"./chunks/framework.yntlMcNk.js";var o=JSON.parse(`{"title":"Sichtbarkeit von Eigenschaften","description":"","frontmatter":{"title":"Sichtbarkeit von Eigenschaften","covers":{"screens":["SCR-032"],"stories":["US-124","US-125"]}},"headers":[],"relativePath":"de/administration/property-visibility.md","filePath":"de/administration/property-visibility.md"}`),s={name:`de/administration/property-visibility.md`};function c(r,o,s,c,l,u){let d=e(`Screenshot`);return a(),n(`div`,null,[o[0]||=t(`<h1 id="sichtbarkeit-von-eigenschaften" tabindex="-1">Sichtbarkeit von Eigenschaften <a class="header-anchor" href="#sichtbarkeit-von-eigenschaften" aria-label="Permalink to “Sichtbarkeit von Eigenschaften”">​</a></h1><p>Manche Eigenschaften sollen nicht alle sehen, die eine Entität lesen dürfen, etwa Investitionskosten oder eine Sicherheitseinstufung. Die Sicherheitsadministration legt für jede Eigenschaft fest, wer ihre Werte sehen und schreiben darf. Du brauchst die Rolle <code>security-admin</code> (Berechtigung <code>visibility:configure</code>); Metamodell-Administratoren können die Sichtbarkeit nicht ändern (siehe <a href="./roles-and-permissions">Rollen und Berechtigungen</a>).</p><div class="warning custom-block"><p class="custom-block-title">Durchsetzung folgt</p><p>In dieser Version konfigurierst du die Sichtbarkeit. Eine Eigenschaft, die nicht <em>Öffentlich</em> ist, bleibt in Katalogen ausgeblendet und lässt sich nicht schreiben, bis Lesen und Schreiben nach Rolle oder Verbindung in den nächsten Versionen folgen.</p></div><h2 id="die-seite" tabindex="-1">Die Seite <a class="header-anchor" href="#die-seite" aria-label="Permalink to “Die Seite”">​</a></h2><p>Öffne <em>Sichtbarkeit von Eigenschaften</em> in der Kopfzeile. Die Seite listet jede Eigenschaft mit den Entitätstypen, die sie verwenden, ihrer Sichtbarkeit und ihrer Einschränkung; eingeschränkte Eigenschaften tragen das Badge <em>Eingeschränkt</em>. Filtere die Liste nach Name.</p>`,5),i(d,{name:`property-visibility`,alt:`Dialog für die Sichtbarkeit einer Eigenschaft mit Lese- und Schreibrollen`}),o[1]||=t(`<h2 id="sichtbarkeit-andern" tabindex="-1">Sichtbarkeit ändern <a class="header-anchor" href="#sichtbarkeit-andern" aria-label="Permalink to “Sichtbarkeit ändern”">​</a></h2><p>Klicke auf den Stift einer Eigenschaft und wähle die Sichtbarkeit:</p><ul><li><strong>Öffentlich:</strong> Alle, die die Entität lesen dürfen, sehen den Wert. Das ist der Standard jeder Eigenschaft.</li><li><strong>Rollenbasiert:</strong> Nur Inhaber der gewählten Leserollen sehen den Wert, und nur Inhaber der gewählten Schreibrollen dürfen ihn ändern. Wähle mindestens eine Leserolle; jede Schreibrolle muss auch eine Leserolle sein. Ohne Schreibrolle darf niemand den Wert ändern.</li><li><strong>Verbindungsbasiert:</strong> Nur Personen, die über den gewählten Verbindungstyp mit der Entität verbunden sind, sehen und ändern den Wert, zum Beispiel eine Domänenarchitektin, die über <em>Domain Assignment</em> verbunden ist. Wählbar sind nur Verbindungstypen.</li></ul><p>Der Dialog zeigt nur die Felder der gewählten Sichtbarkeit und weist auf eine fehlende Auswahl hin, bevor er speichert. Jede Änderung wird als <code>visibility.changed</code> ins Audit-Log geschrieben; eine Änderung, die eine deiner eigenen Rollen begünstigt, wird als selbstbegünstigend markiert.</p><p>Solange ein Verbindungstyp für eine verbindungsbasierte Eigenschaft verwendet wird, braucht das Anlegen von Verbindungen dieses Typs die Berechtigung <code>visibility-scope:assign</code> (Rolle <code>security-admin</code>), damit sich niemand selbst Zugriff verschafft. Ein solcher Verbindungstyp lässt sich nicht löschen.</p><p>In der Metamodell-Konfiguration tragen eingeschränkte Eigenschaften das Badge <em>Eingeschränkt</em>, und der Dialog einer Eigenschaft zeigt ihre Sichtbarkeit nur lesend (siehe <a href="./metamodel-editing">Metamodell bearbeiten</a>).</p><h2 id="uber-die-api" tabindex="-1">Über die API <a class="header-anchor" href="#uber-die-api" aria-label="Permalink to “Über die API”">​</a></h2><ul><li><p><code>GET /admin/property-visibility</code> listet die Sichtbarkeit jeder Eigenschaft mit <code>visibilityMode</code>, <code>readRoles</code>, <code>writeRoles</code>, <code>scopingConnectionType</code> und den Entitätstypen in <code>metatypes</code>.</p></li><li><p><code>PUT /admin/property-visibility</code> ändert die aufgeführten Eigenschaften in einem Schritt, zum Beispiel:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --arg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PROPERTY_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;[{propertyDefId: $id, visibilityMode: &quot;role-restricted&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  readRoles: [&quot;enterprise-architect&quot;, &quot;auditor&quot;], writeRoles: [&quot;enterprise-architect&quot;]}]&#39;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @-</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/admin/property-visibility&quot;</span></span></code></pre></div><p>Ein ungültiger Eintrag antwortet mit <code>422</code> und dem Feld in <code>invalidFields</code>, etwa <code>[0].readRoles</code>, und nichts wird geändert.</p></li></ul><p>Beide brauchen <code>visibility:configure</code>.</p>`,9)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};